"""Build the source walkthrough from reviewed modules and executed proof."""
from pathlib import Path
from html import escape
import json

root = Path(__file__).resolve().parent.parent
research = (root / 'research-engine.js').read_text()
lab = (root / 'lab-engine.js').read_text()
proof = json.loads((root / 'proof/research-verification.json').read_text())

def excerpt(source, start, end):
    a = source.index(start)
    return source[a:source.index(end, a)].strip()

flow = '''<svg class="architecture-flow" viewBox="0 0 1020 150" role="img" aria-label="Confirmed CSV mapping, immutable experiment copies, full quality checks and reference comparison, then reproducible local evidence"><g fill="none" stroke="#C9D0C9"><rect x="1" y="15" width="220" height="110"/><path d="M222 70h38"/><rect x="261" y="15" width="220" height="110"/><path d="M482 70h38"/><rect x="521" y="15" width="220" height="110"/><path d="M742 70h38"/><rect x="781" y="15" width="238" height="110"/></g><g fill="#151A18" font-family="Helvetica,Arial" font-size="17"><text x="20" y="52">01 Confirm</text><text x="280" y="52">02 Experiment</text><text x="540" y="52">03 Compare</text><text x="800" y="52">04 Reproduce</text></g><g fill="#667670" font-family="Menlo,monospace" font-size="12"><text x="20" y="82">Columns + explicit units</text><text x="20" y="102">Only recorded channels</text><text x="280" y="82">Original + modified copy</text><text x="280" y="102">Full-recording QC</text><text x="540" y="82">Actual aligned samples</text><text x="540" y="102">Tolerance + uncertainty</text><text x="800" y="82">Protocol + source + settings</text><text x="800" y="102">Local JSON / workspace</text></g></svg>'''

sections = [
    ('mapping-code', '01 · Bounded, confirmed input', 'Columns and units are confirmed before import. Seconds/milliseconds, temperature and wetness conversions are explicit. Blank selected readings remain missing; unselected sensors remain absent. No units are inferred from raw voltages.', excerpt(research, 'export function parseMappedCSV(', '  const hashSrc = text'), 'research-engine.js'),
    ('comparison-code', '02 · Differences with an uncertainty boundary', 'One-to-one nearest actual samples are aligned under declared limits. No interpolation or extrapolation fills missing reference evidence. The result is a relative discrepancy, not proof that a sensor or reference is correct.', excerpt(research, '    const delta = sensorVal - refVal;', '  const counts = '), 'research-engine.js'),
    ('provenance-code', '03 · Imported data cannot acquire a synthetic score', 'The private WeakSet records locally generated trace ownership. Editing a kind label or restoring a workspace cannot turn imported measurements into classifier evidence. Saved operation descriptions remain unverified metadata.', excerpt(lab, '  const isOwned = OWNED_TRACES.has(trace);', '  const evidenceIndices = []'), 'lab-engine.js'),
    ('report-code', '04 · Export the applied analysis', 'Reports require the matching engine-produced analysis and protocol. The UI adds the applied reference/options. Workspace validation and comparison are completed before state replacement, so a failed restore preserves the current investigation.', excerpt(lab, 'export function createReport(', 'export function sampleCSV('), 'lab-engine.js'),
]

parts = ['''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="author" content="Rishik Rontala"><meta http-equiv="Content-Security-Policy" content="default-src 'self'; script-src 'self'; style-src 'self'; connect-src 'none'; object-src 'none'"><title>Patchline Lab — architecture and proof</title><link rel="stylesheet" href="../lab.css"><link rel="icon" href="../favicon.svg"></head><body><header class="site"><a href="../index.html">Patchline Lab</a><span>Architecture / executed proof</span></header><main class="code-walkthrough"><section class="technical-intro"><p class="eyebrow">Built by Rishik Rontala · Browser only</p><h1>From recording<br>to reproducible evidence.</h1><p>Pure experiment, research, economics and buyer-value engines. Native browser interface. No dependencies, backend, account or runtime AI service.</p>''' + flow + '''<p><strong>lab-engine.js</strong>: immutable perturbations and full quality checks. <strong>research-engine.js</strong>: mapping, comparison, protocol and workspace validation. <strong>economics-engine.js</strong>: explicit assumptions and finite unit economics. <strong>buyer-value-engine.js</strong>: comparable task time, signed buyer value and upfront payback. <strong>lab-app.js + workbench.js</strong>: presentation and applied-state coordination.</p></section>''']
for ident, title, context, code, filename in sections:
    parts.append(f'<section id="{ident}" class="code-section"><h2>{escape(title)}</h2><p>{escape(context)}</p><pre><code>{escape(code)}</code></pre><p class="help">Exact excerpt from <a href="../{filename}">{filename}</a>.</p></section>')

performance = proof['performance']
parts.append(f'''<section id="verification" class="code-section"><h2>05 · Executed engineering proof</h2><p><strong>112 automated tests</strong> cover parsers, channel absence, unit conversion, boundaries, provenance, restore atomicity, report binding and finite finance. Three browser suites verify 51 workflow groups, desktop/mobile layout, downloads, print and no runtime external requests.</p><p><strong>120 / 120 independent comparison cases passed.</strong> Six analytic families cover shared changes, relative offsets, below-tolerance changes, uncertainty boundaries, missing reference readings and reference jumps. These are software cases under fixed assumptions; no sensor-fault accuracy is claimed.</p><p><strong>5,000 preserved UCI temperature readings.</strong> The end-to-end recorded-data proof retains {proof['external']['qualityFindings']} sampling gaps. Labelled injected drift is compared with the original, with 100% usable coverage. Environmental recording interoperability does not validate bandage hardware.</p><p>Measured Node core pipeline, {performance['repetitions']} repetitions: median {performance['medianMs']:.2f} ms, p95 {performance['p95Ms']:.2f} ms on the development Mac. Work includes parse, quality checks, simulated perturbation and reference comparison; excludes browser rendering, downloads and user task time.</p><p><a href="../proof/research-verification.json">Complete executed cases and timings</a> · <a href="../submission/VERIFICATION.md">Verification scope</a></p></section>''')
parts.append('''<section id="scale" class="code-section"><h2>06 · Scale and boundaries</h2><p>Quality checks scan every selected channel. Reference alignment advances through ordered arrays. Chart reduction affects display only; evidence and exports retain every row. Current bounds: 1 MiB / 5,000 CSV rows, 4 MiB workspace, 32 KiB protocol. Per-tab processing avoids a shared compute bottleneck; larger streaming files, team accounts and collaboration require a separate architecture.</p><p>The inherited shape-only fault benchmark still detects 75 / 100 injected faults, misses 25 smooth drifts, and flags 0 / 100 clean traces. Reference comparison is additional evidence and does not rewrite those historical results.</p><p>GLM 5.2 generated add-on code as a coding assistant. Local review corrected the implementation; independent tests verify behavior. Featherless credentials and generation logs are absent from the release. The application never calls an AI provider.</p><p><a href="../LIMITATIONS.md">Limitations</a> · <a href="../README.md">Source and run instructions</a> · <a href="../index.html">Return to the app</a></p></section></main><footer class="site">Built by Rishik Rontala</footer></body></html>''')
(root / 'submission/technical-walkthrough.html').write_text('\n'.join(parts))
